   public List<Item> init_List_I(int max) {
      if (max <= 0) {
         return List.of();
      }

      if (this.init_UiHelper_F == null && (this.write_List == null || this.init_EventBus.init_J() - this.f_f_J >= 10L)) {
         this.init_UiHelper_F = new UiHelper.F();
      }

      if (this.init_UiHelper_F != null && this.f_g_J != this.init_EventBus.init_J()) {
         this.f_g_J = this.init_EventBus.init_J();
         if (this.init_UiHelper_F.init_Z()) {
            this.write_List = this.init_UiHelper_F.init_List();
            this.init_UiHelper_F = null;
            this.f_f_J = this.init_EventBus.init_J();
         }
      }

      LinkedHashSet<Item> out = new LinkedHashSet<>();
      if (this.init_Item != null) {
         out.add(this.init_Item);
      }

      if (this.init_UiHelper_J == UiHelper.J.write && !this.init_Long2ObjectLinkedO.isEmpty()) {
         Item item = this.init_Long2ObjectLinkedO.get(this.init_Long2ObjectLinkedO.firstLongKey()).item();
         if (item != Items.AIR && out.size() < max) {
            out.add(item);
         }
      }

      if (this.write_List != null) {
         for (Item item : this.write_List) {
            if (out.size() >= max) {
               break;
            }

            out.add(item);
         }
      }

      return new ArrayList<>(out);
   }

