   Int2ObjectOpenHashMap<BlockPos> init_Int2ObjectOpenHash() {
      if (this.write_Int2ObjectOpenHash != null) {
         return this.write_Int2ObjectOpenHash;
      }

      this.write_Int2ObjectOpenHash = new Int2ObjectOpenHashMap<>();
      if (!init_Z) {
         return this.write_Int2ObjectOpenHash;
      }

      for (int i = 0; i < this.init_ListPoolArr.length; i++) {
         ListPool t = this.init_ListPoolArr[i];
         if (t.kind() == autismclient.ai.b.ListPool.Inner_DataUtil.init && t.wanted().getBlock() instanceof BaseRailBlock rail) {
            RailShape shape = t.wanted().getValue(rail.getShapeProperty());
            Direction var10000;
            switch (shape) {
               case ASCENDING_EAST:
                  var10000 = Direction.EAST;
                  break;
               case ASCENDING_WEST:
                  var10000 = Direction.WEST;
                  break;
               case ASCENDING_NORTH:
                  var10000 = Direction.NORTH;
                  break;
               case ASCENDING_SOUTH:
                  var10000 = Direction.SOUTH;
                  break;
               default:
                  var10000 = null;
            }

            Direction up = var10000;
            if (up != null) {
               BlockPos helper = t.pos().relative(up).above();
               if (this.init_Long2IntOpenHashMa.get(helper.asLong()) < 0) {
                  boolean alone = true;

                  for (Direction side : Plane.HORIZONTAL) {
                     for (int dy = -1; dy <= 1 && alone; dy++) {
                        long key = helper.relative(side).offset(0, dy, 0).asLong();
                        int j = this.init_Long2IntOpenHashMa.get(key);
                        if (j >= 0 && j != i && this.init_ListPoolArr[j].wanted().getBlock() instanceof BaseRailBlock) {
                           alone = false;
                        }
                     }
                  }

                  if (alone) {
                     this.write_Int2ObjectOpenHash.put(i, helper);
                  }
               }
            }
         }
      }

      return this.write_Int2ObjectOpenHash;
   }

