   private void init_V_I_2(int start, IntArrayList[] preds, int[] mark) {
      if (preds[start] != null && !preds[start].isEmpty()) {
         ArrayDeque<int[]> stack = new ArrayDeque<>();
         stack.push(new int[]{start, 0});
         mark[start] = 1;

         while (!stack.isEmpty()) {
            int[] top = stack.peek();
            int v = top[0];
            if (preds[v] != null && top[1] < preds[v].size()) {
               int w = preds[v].getInt(top[1]);
               if (mark[w] == 1) {
                  preds[v].removeInt(top[1]);
               } else {
                  top[1]++;
                  if (mark[w] == 0) {
                     mark[w] = 1;
                     stack.push(new int[]{w, 0});
                  }
               }
            } else {
               mark[v] = 2;
               stack.pop();
            }
         }
      } else {
         mark[start] = 2;
      }
   }

