   private UiHelper.Inner_NetHelper init_UiHelper_NetHelper_BlockPos(BlockPos here, double feetY, IntArrayList goals, BlockState tempState, Item temp) {
      LongOpenHashSet stances = new LongOpenHashSet();
      Long2IntOpenHashMap goalOf = new Long2IntOpenHashMap();
      int looked = 0;

      for (int g : goals) {
         if (looked++ >= 8) {
            break;
         }

         UiHelper.aM w = this.init_UiHelper_aM_I_2(g, -9223372036854775808L, true);
         if (w != null && w != init_UiHelper_aM) {
            long last = this.write_Long2LongOpenHashM.getOrDefault(w.stance(), -4611686018427387904L);
            if (this.init_EventBus.init_J() - last >= 800L) {
               stances.add(w.stance());
               goalOf.put(w.stance(), g);
            }
         }
      }

      if (stances.isEmpty()) {
         return null;
      }

      for (long k : stances) {
         this.write_Long2LongOpenHashM.put(k, this.init_EventBus.init_J());
      }

      StreamUtil search = new StreamUtil(this, 80.0);
      search.load_I = StreamUtil.init_I_UiHelper_IntArrayList(this, goals);
      StreamUtil.Inner_BufferHelper plan = search.init_StreamUtil_BufferH_BlockPos_2(here, feetY, stances, tempState, 20000);
      if (plan != null && !plan.steps().isEmpty()) {
         int g = goalOf.get(search.read_J);
         this.init_V_Str(
            "access plan (to a clicking stance): "
               + plan.steps().size()
               + " steps, "
               + plan.temps()
               + " temporary, toward "
               + this.init_ListPoolArr[g].pos().toShortString()
               + " from "
               + BlockPos.of(search.read_J).toShortString()
               + " ("
               + init_Str_StreamUtil_BufferH(plan)
               + ")"
         );
         this.f_b_I = g;
         this.f_c_I = this.poll_I;
         this.load_Str = "Getting into position (" + plan.steps().size() + " steps)";
         return new UiHelper.Inner_TaskQueue(plan, temp);
      } else {
         this.init_V_Str("access: no way onto " + stances.size() + " stances that click the lowest cells (" + search.init_Str + ")");
         return null;
      }
   }

   static String init_Str_StreamUtil_BufferH(StreamUtil.Inner_BufferHelper plan) {
      StringBuilder out = new StringBuilder();

      for (StreamUtil.Inner_NetHelper st : plan.steps()) {
         if (out.length() > 0) {
            out.append(", ");
         }

         out.append(st.kind().name().charAt(0)).append(' ').append(BlockPos.of(st.to()).toShortString());
      }

      return out.toString();
   }

