   private BlockPos load_BlockPos_BlockPos_Fluid(BlockPos source, Fluid fluid) {
      this.set_LongOpenHashSet.clear();
      this.set_LongOpenHashSet.add(source.asLong());
      Long2IntOpenHashMap seen = new Long2IntOpenHashMap();
      seen.defaultReturnValue(-1);
      ArrayDeque<long[]> queue = new ArrayDeque<>();
      boolean water = fluid.isSame(Fluids.WATER);
      int reach = fluid.isSame(Fluids.LAVA) ? 3 : 7;
      queue.add(new long[]{source.asLong(), reach});
      seen.put(source.asLong(), reach);
      int budget = 6000;

      while (!queue.isEmpty() && budget-- > 0) {
         long[] e = queue.poll();
         BlockPos at = BlockPos.of(e[0]);
         int left = (int)e[1];
         int ti = this.init_Long2IntOpenHashMa.get(at.asLong());
         boolean sourceCell = at.equals(source)
            || this.init_ArrayUtil.getBlockState(at).getFluidState().isSource()
            || ti >= 0
               && this.init_ListPoolArr[ti].kind() == autismclient.ai.b.ListPool.Inner_DataUtil.read
               && this.init_ListPoolArr[ti].wanted().getFluidState().getType().isSame(fluid);
         if (sourceCell) {
            left = reach;
         }

         BlockPos below = at.below();
         if (!this.init_EventBus.load_Z(below)) {
            return below;
         }

         boolean down = this.init_Z_BlockPos_Fluid(below, fluid);
         if (down) {
            BlockPos bad = this.read_BlockPos_BlockPos_Fluid(below, fluid);
            if (bad != null && this.count_Z) {
               return bad;
            }

            if (seen.get(below.asLong()) < reach) {
               seen.put(below.asLong(), reach);
               queue.add(new long[]{below.asLong(), reach});
               this.set_LongOpenHashSet.add(below.asLong());
            }
         }

         if ((!down || sourceCell) && left > 0) {
            for (Direction d : Plane.HORIZONTAL) {
               BlockPos next = at.relative(d);
               if (!this.init_EventBus.load_Z(next)) {
                  return next;
               }

               if (this.count_Z && water && sourceCell) {
                  BlockPos footing = this.init_BlockPos_BlockPos_BlockPos(at, next);
                  if (footing != null) {
                     return footing;
                  }
               }

               UiHelper.aB shaped = ti < 0 ? null : this.init_UiHelper_aB_I(ti);
               if ((shaped == null || !shaped.load_List.contains(next) || !this.load_Z_UiHelper_aB(shaped)) && this.init_Z_BlockPos_Fluid(next, fluid)) {
                  BlockPos bad = this.read_BlockPos_BlockPos_Fluid(next, fluid);
                  if (bad != null && this.count_Z) {
                     return bad;
                  }

                  if (seen.get(next.asLong()) < left - 1) {
                     seen.put(next.asLong(), left - 1);
                     this.set_LongOpenHashSet.add(next.asLong());
                     queue.add(new long[]{next.asLong(), left - 1});
                  }
               }
            }
         }
      }

      return queue.isEmpty() ? null : BlockPos.of(queue.peek()[0]);
   }

   private BlockPos init_BlockPos_BlockPos_BlockPos(BlockPos incoming, BlockPos dry) {
      BlockPos below = dry.below();
      long key = below.asLong();
      if (!this.init_Long2ObjectOpenHas.containsKey(key) && !this.init_ArrayUtil.load_Z_BlockPos(below)) {
         return null;
      }

      BlockState boundary = this.init_ArrayUtil.getBlockState(dry);
      BooleanProperty property = BlockStateProperties.WATERLOGGED;
      if (boundary.hasProperty(property) && !boundary.getValue(property) && this.init_ArrayUtil.getBlockState(below).isSolid()) {
         int sourceCell = this.init_Long2IntOpenHashMa.get(dry.asLong());
         if (sourceCell >= 0 && !this.init_ListPoolArr[sourceCell].wanted().getFluidState().isEmpty()) {
            return null;
         }

         for (Direction side : Plane.HORIZONTAL) {
            BlockPos other = dry.relative(side);
            if (!other.equals(incoming)) {
               FluidState water = this.init_ArrayUtil.getFluidState(other);
               if (!this.init_EventBus.load_Z(other) || water.isSource() && water.is(FluidTags.WATER)) {
                  if (!this.init_ArrayUtil.init_Z() && this.init_Long2ObjectOpenHas.containsKey(key)) {
                     this.pop_LongOpenHashSet.add(key);
                  }

                  return below;
               }
            }
         }

         return null;
      } else {
         return null;
      }
   }

   private boolean init_Z_BlockPos_Fluid(BlockPos p, Fluid fluid) {
      if (!this.init_Long2ObjectOpenHas.containsKey(p.asLong()) && !this.init_ArrayUtil.load_Z_BlockPos(p)) {
         BlockState s = this.init_ArrayUtil.getBlockState(p);
         if (s == ArrayUtil.init_BlockState) {
            return false;
         } else {
            FluidState held = s.getFluidState();
            if (!held.isEmpty()) {
               return held.getType().isSame(fluid);
            } else if (s.isAir()) {
               return true;
            } else {
               return s.getBlock() instanceof LiquidBlockContainer
                  ? false
                  : s.canBeReplaced(fluid) || !s.isSolid() && !s.isCollisionShapeFullBlock(this.init_ArrayUtil, p);
            }
         }
      } else {
         return true;
      }
   }

   private BlockPos read_BlockPos_BlockPos_Fluid(BlockPos p, Fluid fluid) {
      int i = this.init_Long2IntOpenHashMa.get(p.asLong());
      if (i >= 0) {
         ListPool t = this.init_ListPoolArr[i];
         if (!t.wanted().getFluidState().isEmpty() && t.wanted().getFluidState().getType().isSame(fluid)) {
            return null;
         }

         if (t.kind() == autismclient.ai.b.ListPool.Inner_DataUtil.write) {
            return null;
         }
      }

      return p;
   }

