   private boolean reset(BlockPos filled) {
      for (Direction direction : Direction.values()) {
         BlockPos inner = filled.relative(direction);
         if (this.run_LongOpenHashSet.contains(inner.asLong()) && this.init_ArrayUtil.getBlockState(inner).isAir()) {
            boolean open = false;

            for (Direction side : Direction.values()) {
               BlockPos exit = inner.relative(side);
               if (!exit.equals(filled)) {
                  int source = this.init_Long2IntOpenHashMa.get(exit.asLong());
                  BlockState state = source < 0 ? this.init_ArrayUtil.getBlockState(exit) : this.init_ListPoolArr[source].wanted();
                  if (state.isAir() || state != ArrayUtil.init_BlockState && state.canBeReplaced()) {
                     open = true;
                     break;
                  }
               }
            }

            if (!open) {
               return false;
            }
         }
      }

      return true;
   }

