   static void init_V_Vec3(Vec3 start, TextFormat.Inner_BufferHelper route, LongOpenHashSet keep) {
      load_V_Vec3_LongOpenHashSet(start, keep);
      Vec3 previous = start;

      for (Vec3 point : route.points()) {
         int samples = Math.max(
            1, (int)Math.ceil(Math.max(Math.abs(point.x - previous.x), Math.max(Math.abs(point.y - previous.y), Math.abs(point.z - previous.z))))
         );
         Vec3 from = previous;

         for (int i = 1; i <= samples; i++) {
            Vec3 to = previous.lerp(point, (double)i / samples);
            AABB a = IoWorker.init(from.x, from.y, from.z, false);
            AABB b = IoWorker.init(to.x, to.y, to.z, false);

            for (int x = ArrayUtil.init_I_D(Math.min(a.minX, b.minX)); x <= ArrayUtil.init_I_D(Math.max(a.maxX, b.maxX)); x++) {
               for (int y = ArrayUtil.init_I_D(Math.min(a.minY, b.minY)) - 1; y <= ArrayUtil.init_I_D(Math.max(a.maxY, b.maxY)); y++) {
                  for (int z = ArrayUtil.init_I_D(Math.min(a.minZ, b.minZ)); z <= ArrayUtil.init_I_D(Math.max(a.maxZ, b.maxZ)); z++) {
                     keep.add(BlockPos.asLong(x, y, z));
                  }
               }
            }

            from = to;
         }

         previous = point;
      }
   }

