      private void load(SyncManager controls, BlockState placed) {
         if (!UiHelper.this.update_List.isEmpty() && placed != null) {
            UiHelper.this.init_ArrayUtil.init_V_BlockPos_BlockState(this.init_ListPool.pos(), placed);

            try {
               autismclient.ai.b.ConfigStore.Inner_DataUtil budget = new autismclient.ai.b.ConfigStore.Inner_DataUtil(1200);
               Vec3 origin = UiHelper.this.init_Vec3();
               if (this.init_Vec3 != null) {
                  IntArrayList local = new IntArrayList();

                  for (int i : this.init_List) {
                     if (!local.contains(i)) {
                        local.add(i);
                     }
                  }

                  for (int i : UiHelper.this.update_List) {
                     if (local.size() < 64 && !local.contains(i)) {
                        local.add(i);
                     }
                  }

                  for (Direction side : Direction.values()) {
                     int i = UiHelper.this.init_Long2IntOpenHashMa.get(this.init_ListPool.pos().relative(side).asLong());
                     if (i >= 0 && !local.contains(i)) {
                        local.add(i);
                     }
                  }

                  for (int i : local) {
                     if (i != this.load_I
                        && !UiHelper.this.init_ArrayUtil.init_Z_BlockPos(UiHelper.this.init_ListPoolArr[i].pos())
                        && UiHelper.this.buffer(i)
                        && UiHelper.this.value(i)) {
                        autismclient.ai.b.ConfigStore.Inner_StreamUtil seed = ConfigStore.init(
                           UiHelper.this.init_ArrayUtil,
                           UiHelper.this.init_EventBus,
                           UiHelper.this.init_PathHelper,
                           UiHelper.this.init_ListPoolArr[i],
                           UiHelper.this.init_ListPoolArr[i].item(),
                           ConfigStore.Inner_CachePool.init,
                           origin,
                           true,
                           false,
                           budget,
                           4.4,
                           UiHelper.this.init_u_DataUtil_I(i),
                           null
                        );
                        if (seed != null) {
                           UiHelper.l preview = UiHelper.this.init_UiHelper_l_Vec3(origin, seed, local, budget, 4);
                           if (preview.cells().size() >= 4) {
                              this.init_Vec3 = null;
                           }
                           break;
                        }
                     }
                  }

                  if (this.init_Vec3 != null
                     && TextFormat.load(UiHelper.this.init_ArrayUtil, this.init_Vec3)
                     && TextFormat.init_Z(UiHelper.this.init_ArrayUtil, origin, this.init_Vec3)) {
                     origin = this.init_Vec3;
                  }
               }

               double ceiling = this.init_D;
               if (UiHelper.this.data(this.load_I)) {
                  boolean x = false;
                  boolean z = false;

                  for (Direction side : Plane.HORIZONTAL) {
                     int neighbor = UiHelper.this.init_Long2IntOpenHashMa.get(this.init_ListPool.pos().relative(side).asLong());
                     if (neighbor >= 0 && UiHelper.this.size(neighbor)) {
                        x |= side.getAxis() == Axis.X;
                        z |= side.getAxis() == Axis.Z;
                     }
                  }

                  int above = UiHelper.this.init_Long2IntOpenHashMa.get(this.init_ListPool.pos().above().asLong());
                  if (x && z && above < 0 && origin.y < this.init_ListPool.pos().getY()) {
                     Vec3 below = new Vec3(origin.x, this.init_ListPool.pos().getY() - 1.8 - 0.25, origin.z);
                     if (TextFormat.load(UiHelper.this.init_ArrayUtil, below) && TextFormat.init_Z(UiHelper.this.init_ArrayUtil, origin, below)) {
                        origin = below;
                        ceiling = this.init_ListPool.pos().getY() - 1.8 - 0.08;
                     }
                  }
               }

               long here = BlockPos.containing(origin).asLong();
               if (!TextFormat.load(UiHelper.this.init_ArrayUtil, origin)) {
                  return;
               }

               IntArrayList nearby = new IntArrayList();

               for (int preferred : this.init_List) {
                  if (!nearby.contains(preferred)) {
                     nearby.add(preferred);
                  }
               }

               for (Direction side : Direction.values()) {
                  int adjacent = UiHelper.this.init_Long2IntOpenHashMa.get(this.init_ListPool.pos().relative(side).asLong());
                  if (adjacent >= 0) {
                     nearby.add(adjacent);
                  }
               }

               for (int i : UiHelper.this.update_List) {
                  if (nearby.size() < 70 && !nearby.contains(i)) {
                     nearby.add(i);
                  }
               }

               autismclient.ai.b.ConfigStore.Inner_StreamUtil best = null;
               double bestScore = -1.0 / 0.0;
               Vec3 eye = IoWorker.init(origin, false);
               BlockHitResult ray = UiHelper.this.init_ArrayUtil
                  .init_BlockHitResult_Vec3_Vec3(
                     eye, eye.add(IoWorker.init_Vec3(UiHelper.this.init_EventBus.write_F(), UiHelper.this.init_EventBus.update_F()).scale(4.4))
                  );
               int aligned = ray == null ? -1 : UiHelper.this.init_Long2IntOpenHashMa.get(ray.getBlockPos().relative(ray.getDirection()).asLong());
               if (aligned >= 0 && nearby.contains(aligned)) {
                  nearby.rem(aligned);
                  nearby.add(0, aligned);
               }

               for (int checked = 0; checked < nearby.size() && !budget.init(); checked++) {
                  int next = nearby.getInt(checked);
                  if (next != this.load_I
                     && !UiHelper.this.close_LongOpenHashSet.contains(UiHelper.init_J_I_J(next, here))
                     && UiHelper.this.buffer(next)
                     && UiHelper.this.value(next)
                     && UiHelper.this.stop(next)
                     && UiHelper.this.init_ConfigStore_CacheP_I(next) == ConfigStore.Inner_CachePool.init) {
                     ListPool candidate = UiHelper.this.init_ListPoolArr[next];
                     if (!(candidate.pos().distToCenterSqr(eye) > 36.0)) {
                        autismclient.ai.b.ConfigStore.Inner_StreamUtil click = next == aligned
                           ? ConfigStore.init(
                              UiHelper.this.init_ArrayUtil,
                              UiHelper.this.init_EventBus,
                              UiHelper.this.init_PathHelper,
                              candidate,
                              candidate.item(),
                              origin,
                              UiHelper.this.init_EventBus.write_F(),
                              UiHelper.this.init_EventBus.update_F(),
                              true,
                              false,
                              budget,
                              4.4,
                              UiHelper.this.init_u_DataUtil_I(next)
                           )
                           : null;
                        boolean keepsRay = click != null;
                        if (click == null) {
                           click = ConfigStore.init(
                              UiHelper.this.init_ArrayUtil,
                              UiHelper.this.init_EventBus,
                              UiHelper.this.init_PathHelper,
                              candidate,
                              candidate.item(),
                              ConfigStore.Inner_CachePool.init,
                              origin,
                              true,
                              false,
                              budget,
                              4.4,
                              UiHelper.this.init_u_DataUtil_I(next),
                              null
                           );
                        }

                        if (click != null) {
                           double yaw = Math.abs(IoWorker.init_F(UiHelper.this.init_EventBus.write_F(), click.yaw()));
                           double pitch = Math.abs(UiHelper.this.init_EventBus.update_F() - click.pitch());
                           double turns = Math.max(0.0, Math.ceil(Math.max(yaw / 60.0, pitch / 45.0)) - 1.0);
                           double material = candidate.item() == this.init_ListPool.item() ? 0.0 : UiHelper.this.read_I_Item(candidate.item());
                           double score = (keepsRay ? 0.5 : 0.0) - (turns + material) * 8.0 - (yaw + pitch) * 0.01;

                           for (Direction side : Direction.values()) {
                              int neighbor = UiHelper.this.init_Long2IntOpenHashMa.get(candidate.pos().relative(side).asLong());
                              if (neighbor >= 0 && neighbor != this.load_I && UiHelper.this.init_BArr[neighbor] == 0 && UiHelper.this.data(neighbor)) {
                                 score += 0.35;
                              }
                           }

                           if (score > bestScore) {
                              bestScore = score;
                              best = click;
                           }

                           if (keepsRay && material == 0.0) {
                              break;
                           }
                        }
                     }
                  }
               }

               if (best != null) {
                  UiHelper.this.init_FArr_SyncManager(controls, best.yaw(), best.pitch());

                  for (int slot = 0; slot < 9; slot++) {
                     if (UiHelper.init_Z_ItemStack_Item(UiHelper.this.init_EventBus.init_ItemStack_I(slot), best.item())) {
                        controls.load_I = slot;
                        break;
                     }
                  }

                  TextFormat.Inner_BufferHelper route = new TextFormat.Inner_BufferHelper(List.of(origin), here);
                  UiHelper.ValueSink work = UiHelper.this.new ValueSink(best.target().index(), null, new UiHelper.i(route, best));
                  work.init_List = this.init_List;
                  work.init_Vec3 = this.init_Vec3;
                  if (best.target().pos().getY() == this.init_ListPool.pos().getY()) {
                     work.init_D = ceiling;
                  }

                  this.init_UiHelper_NetHelper = work;
                  return;
               }
            } finally {
               UiHelper.this.init_ArrayUtil.init_V_BlockPos(this.init_ListPool.pos());
            }
         }
      }

